# Bitmask states; each operation retains center and incomparable points.
inc=[]
for k,(x,y) in enumerate(pts):
    m=1<<k
    for i,(a,b) in enumerate(pts):
        if i!=k and ((a<x and b>y) or (a>x and b<y)):
