import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a_values = data[1:]

    # For each prime, store its exponent in every adjacent ratio A_i.
    exponents = {}
    for i, value in enumerate(a_values):
        x = value
        d = 2
        while d * d <= x:
            if x % d == 0:
                e = 0
                while x % d == 0:
                    x //= d
                    e += 1
                exponents.setdefault(d, [0] * (n - 1))[i] = e
            d += 1
        if x > 1:
            exponents.setdefault(x, [0] * (n - 1))[i] = 1

    answer = 1
    for prime, edge_exponents in exponents.items():
        total = sum(edge_exponents)
        powers = [1] * (total + 1)
        for h in range(1, total + 1):
            powers[h] = powers[h - 1] * prime % MOD

        # dp[h] sums scores for the processed vertices when the current
        # valuation is h above the minimum valuation seen so far.
        dp = [1]
        max_height = 0
        for i, e in enumerate(edge_exponents, start=1):
            next_dp = [0] * (max_height + e + 1)
            if e == 0:
                # The valuation does not change; include the new vertex's factor.
                for h, ways in enumerate(dp):
                    next_dp[h] = ways * powers[h] % MOD
            else:
                for h, ways in enumerate(dp):
                    if ways == 0:
                        continue
                    # The prime's entire exponent on this edge is assigned
                    # either to the numerator or to the denominator.
                    new_h = h + e
                    next_dp[new_h] = (next_dp[new_h] + ways * powers[new_h]) % MOD

                    new_h = h - e
                    if new_h >= 0:
                        next_dp[new_h] = (next_dp[new_h] + ways * powers[new_h]) % MOD
                    else:
                        # A new minimum is reached. All i previous vertex
                        # valuations shift up by -new_h; the new one is zero.
                        delta = -new_h
                        next_dp[0] = (next_dp[0] + ways * pow(prime, delta * i, MOD)) % MOD
            max_height += e
            dp = next_dp

        answer = answer * sum(dp) % MOD

    print(answer)

if __name__ == '__main__':
    main()

