from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            events[b].append((a, i))

        heap = []
        gains = [0] * len(conflictingPairs)
        base = 0

        for r in range(1, n + 1):
            for a, i in events[r]:
                heapq.heappush(heap, (-a, i))

            if not heap:
                base += r
                continue

            top_item = heapq.heappop(heap)
            top = -top_item[0]
            second = -heap[0][0] if heap else 0
            heapq.heappush(heap, top_item)

            base += r - top
            if top > second:
                gains[top_item[1]] += top - second

        return base + max(gains)

