import sys
input = sys.stdin.readline

N, M, Q = map(int, input().split())
edges = []
for _ in range(M):
    a, b, c = map(int, input().split())
    edges.append((a - 1, b - 1, c))

queries = []
ever_closed = [False] * M
for _ in range(Q):
    parts = list(map(int, input().split()))
    if parts[0] == 1:
        idx = parts[1] - 1
        ever_closed[idx] = True
        queries.append((1, idx))
    else:
        queries.append((2, parts[1] - 1, parts[2] - 1))

INF = 10**30
dist = [[INF] * N for _ in range(N)]
for i in range(N):
    dist[i][i] = 0
for idx, (u, v, w) in enumerate(edges):
    if not ever_closed[idx]:
        dist[u][v] = dist[v][u] = w

# APSP among the roads that remain open at the end.
for k in range(N):
    row_k = dist[k]
    for i in range(N):
        dik = dist[i][k]
        if dik == INF:
            continue
        row_i = dist[i]
        for j in range(N):
            candidate = dik + row_k[j]
            if candidate < row_i[j]:
                row_i[j] = candidate

answers = []
for query in reversed(queries):
    if query[0] == 2:
        _, x, y = query
        value = dist[x][y]
        answers.append(str(value if value < INF else -1))
    else:
        _, idx = query
        u, v, w = edges[idx]
        # Snapshot distances to the endpoints before applying this insertion.
        to_u = [dist[i][u] for i in range(N)]
        to_v = [dist[i][v] for i in range(N)]
        for i in range(N):
            row = dist[i]
            via_u = to_u[i] + w
            via_v = to_v[i] + w
            for j in range(N):
                candidate = via_u + to_v[j]
                if candidate < row[j]:
                    row[j] = candidate
                candidate = via_v + to_u[j]
                if candidate < row[j]:
                    row[j] = candidate

print("\n".join(reversed(answers)))

