import sys
import math


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    processes = [data[i:i + 4] for i in range(2, len(data), 4)]

    def feasible(target):
        total_cost = 0
        for a, p, b, q in processes:
            g = math.gcd(a, b)
            # The two bundles below have equal throughput. Bound the count
            # of whichever type has the more expensive equal-throughput bundle.
            if (b // g) * p <= (a // g) * q:
                # S bundle is no more expensive, so enumerate T counts.
                best = 10**30
                for y in range(a // g):
                    remaining = target - b * y
                    x = (remaining + a - 1) // a if remaining > 0 else 0
                    cost = y * q + x * p
                    if cost < best:
                        best = cost
            else:
                # T bundle is cheaper, so enumerate S counts.
                best = 10**30
                for x in range(b // g):
                    remaining = target - a * x
                    y = (remaining + b - 1) // b if remaining > 0 else 0
                    cost = x * p + y * q
                    if cost < best:
                        best = cost
            total_cost += best
            if total_cost > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)


if __name__ == '__main__':
    main()

class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 10**9 + 7
        dp = [0] * (x + 1)
        dp[0] = 1

        for i in range(1, n + 1):
            ndp = [0] * (x + 1)
            for k in range(1, min(i, x) + 1):
                # The last performer uses an existing stage, or introduces
                # a new stage and its band's score.
                ndp[k] = (k * dp[k] + (x - k + 1) * y * dp[k - 1]) % mod
            dp = ndp

        return sum(dp) % mod

