class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)

        # A positive number with c set bits takes 1 + steps(c) operations,
        # except that c == 1 is already 1 after that one operation as well.
        good = [False] * (n + 1)
        for c in range(1, n + 1):
            x = c
            steps = 0
            while x > 1:
                x = x.bit_count()
                steps += 1
            good[c] = (c == 1 or steps + 1 <= k)

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i % MOD
        inv_fact = [1] * (n + 1)
        inv_fact[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        def choose(a: int, b: int) -> int:
            if b < 0 or b > a:
                return 0
            return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

        # Count numbers smaller than s by first differing at a 1-bit of s.
        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for suffix_ones in range(remaining + 1):
                    total_ones = prefix_ones + suffix_ones
                    if total_ones > 0 and good[total_ones]:
                        answer = (answer + choose(remaining, suffix_ones)) % MOD
                prefix_ones += 1

        return answer

