import sys
import heapq

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    graph = [row.decode() for row in data[1:1 + n]]

    # incoming[u][c] contains vertices x with an edge x -> u labeled c.
    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]

    for u in range(n):
        for v, ch in enumerate(graph[u]):
            if ch != '-':
                c = ord(ch) - 97
                outgoing[u][c].append(v)
                incoming[v][c].append(u)

    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    heap = []

    # Empty paths and one-edge paths are the centers of palindromes.
    for u in range(n):
        dist[u][u] = 0
        heapq.heappush(heap, (0, u, u))
        for v, ch in enumerate(graph[u]):
            if ch != '-' and dist[u][v] > 1:
                dist[u][v] = 1
                heapq.heappush(heap, (1, u, v))

    while heap:
        d, u, v = heapq.heappop(heap)
        if d != dist[u][v]:
            continue
        # Paths of length 0 or 1 are already shortest.
        if d <= 1:
            continue

        for c in range(26):
            left = incoming[u][c]
            right = outgoing[v][c]
            nd = d + 2
            for x in left:
                row = dist[x]
                for y in right:
                    if nd < row[y]:
                        row[y] = nd
                        heapq.heappush(heap, (nd, x, y))

    out = []
    for row in dist:
        out.append(' '.join(str(x if x < inf else -1) for x in row))
    sys.stdout.write('\n'.join(out))

if __name__ == "__main__":
    main()

