import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    m = next(it)
    rows = [0] * n
    for _ in range(m):
        u = next(it) - 1
        v = next(it) - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduce the adjacency matrix over GF(2) to reduced row-echelon form.
    a = rows[:]
    pivots = []
    r = 0
    for c in range(n):
        p = next((i for i in range(r, n) if (a[i] >> c) & 1), None)
        if p is None:
            continue
        a[r], a[p] = a[p], a[r]
        for i in range(n):
            if i != r and ((a[i] >> c) & 1):
                a[i] ^= a[r]
        pivots.append(c)
        r += 1

    pivot_set = set(pivots)
    basis = []
    for free in range(n):
        if free in pivot_set:
            continue
        vec = 1 << free
        for i, col in enumerate(pivots):
            if (a[i] >> free) & 1:
                vec |= 1 << col
        basis.append(vec)

    # Each coordinate vector in the nullspace can be used as one bit
    # of the labels. Every vertex must occur in some nullspace vector.
    if any(not any((vec >> v) & 1 for vec in basis) for v in range(n)):
        print("No")
        return

    ans = [0] * n
    for bit, vec in enumerate(basis):
        for v in range(n):
            if (vec >> v) & 1:
                ans[v] |= 1 << bit

    # Leave room under the allowed 60-bit bound when possible.
    if n > 1 and max(ans, default=0) < (1 << 58):
        ans = [x * 4 for x in ans]
    print("Yes")
    print(*ans)

if __name__ == "__main__":
    main()

