import math

N = int(input())
answer = None

# Let d = x - y. Then N = d * (3*y^2 + 3*d*y + d^2),
# and d^3 <= N. For each possible d, solve the resulting quadratic in y.
for d in range(1, 1_000_001):
    if d * d * d > N:
        break
    if N % d != 0:
        continue

    q = N // d
    discriminant = 12 * q - 3 * d * d
    if discriminant < 0:
        continue
    root = math.isqrt(discriminant)
    if root * root != discriminant:
        continue

    numerator = root - 3 * d
    if numerator % 6 != 0:
        continue
    y = numerator // 6
    if y > 0:
        answer = (y + d, y)
        break

if answer is None:
    print(-1)
else:
    print(*answer)

