import bisect

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    n, q = map(int, data[:2])
    s = data[2].decode()
    ones, twos, slashes = [], [], []
    for i, c in enumerate(s, 1):
        if c == '1':
            ones.append(i)
        elif c == '2':
            twos.append(i)
        else:
            slashes.append(i)

    out = []
    idx = 3
    for _ in range(q):
        L, R = int(data[idx]), int(data[idx + 1])
        idx += 2
        one_start = bisect.bisect_left(ones, L)
        two_end = bisect.bisect_right(twos, R)

        def feasible(k):
            if k:
                one_idx = one_start + k - 1
                two_idx = two_end - k
                if one_idx >= len(ones) or two_idx < 0:
                    return False
                last_one = ones[one_idx]
                first_two = twos[two_idx]
                if last_one > R or first_two < L:
                    return False
                low, high = last_one + 1, first_two - 1
            else:
                low, high = L, R
            if low > high:
                return False
            return bisect.bisect_left(slashes, low) < bisect.bisect_right(slashes, high)

        low, high = 0, (R - L + 1) // 2 + 1
        while low + 1 < high:
            mid = (low + high) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid
        out.append(str(2 * low + 1 if feasible(0) else 0))

    sys.stdout.write('\n'.join(out))

