class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # Each choice in the first half determines its mirrored digit.
        # Its coefficient is the total place-value contribution modulo k.
        powers = [1 % k]
        for _ in range(n):
            powers.append((powers[-1] * 10) % k)

        coeff = []
        for i in range(m):
            j = n - 1 - i
            c = powers[i]
            if i != j:
                c += powers[j]
            coeff.append(c % k)

        # suffix[i][r] says whether positions i..m-1 can contribute
        # residue r modulo k.
        suffix = [None] * (m + 1)
        suffix[m] = bytes([1] + [0] * (k - 1))
        for i in range(m - 1, -1, -1):
            following = suffix[i + 1]
            row = bytearray(k)
            c = coeff[i]
            for residue in range(k):
                for digit in range(10):
                    if following[(residue - digit * c) % k]:
                        row[residue] = 1
                        break
            suffix[i] = bytes(row)

        chosen = []
        residue = 0
        for i, c in enumerate(coeff):
            smallest = 1 if i == 0 else 0
            for digit in range(9, smallest - 1, -1):
                needed = (-residue - digit * c) % k
                if suffix[i + 1][needed]:
                    chosen.append(str(digit))
                    residue = (residue + digit * c) % k
                    break

        half = ''.join(chosen)
        if n % 2:
            return half + half[-2::-1]
        return half + half[::-1]

