class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))

            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        occ_a = occurrences(a)
        occ_b = occurrences(b)
        occ_c = occurrences(c)

        best = n + 1
        for start_b in occ_b:
            if a:
                k = bisect_right(occ_a, start_b - len(a)) - 1
                if k < 0:
                    continue
                start = occ_a[k]
            else:
                start = start_b

            after_b = start_b + len(b)
            if c:
                k = bisect_left(occ_c, after_b)
                if k == len(occ_c):
                    continue
                end = occ_c[k] + len(c)
            else:
                end = after_b

            best = min(best, end - start)

        return -1 if best == n + 1 else best

