    if k > n - k:
        r = n - k
        base = 0
        for value in a:
            base ^= value
    else:
        r = k
        base = 0

    answer = 0
    for indices in itertools.combinations(range(n), r):
        value = base
        for i in indices:
            value ^= a[i]
        if value > answer:
            answer = value
    print(answer)

