from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Prefix indices with the same residue modulo k define lengths divisible by k.
        min_prefix = [None] * k
        min_prefix[0] = 0
        prefix = 0
        best = None

        for j, value in enumerate(nums, 1):
            prefix += value
            r = j % k

            # Use only an earlier prefix, ensuring a nonempty subarray.
            if min_prefix[r] is not None:
                total = prefix - min_prefix[r]
                if best is None or total > best:
                    best = total

            if min_prefix[r] is None or prefix < min_prefix[r]:
                min_prefix[r] = prefix

        return best

