from typing import List

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        strings = [str(x) for x in nums]

        def almost_equal(a: str, b: str) -> bool:
            if a == b:
                return True

            # Try performing the swap on either integer. Parsing the result as
            # an integer naturally handles any leading zero created by a swap.
            for source, target in ((a, b), (b, a)):
                digits = list(source)
                target_value = int(target)
                for i in range(len(digits)):
                    for j in range(i + 1, len(digits)):
                        if digits[i] == digits[j]:
                            continue
                        digits[i], digits[j] = digits[j], digits[i]
                        if int(''.join(digits)) == target_value:
                            return True
                        digits[i], digits[j] = digits[j], digits[i]
            return False

        answer = 0
        for i in range(len(nums)):
            for j in range(i):
                if almost_equal(strings[i], strings[j]):
                    answer += 1
        return answer

