from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        # Each reachable index i contributes the line
        # dp[i] + (x - i) * nums[i] at destination x.
        # A Li Chao tree maintains the maximum of these lines.
        tree = [None] * (4 * n)

        def add(line, node, lo, hi):
            current = tree[node]
            if current is None:
                tree[node] = line
                return

            mid = (lo + hi) // 2
            if line[0] * mid + line[1] > current[0] * mid + current[1]:
                tree[node], line = line, current
                current = tree[node]

            if lo == hi:
                return
            if line[0] * lo + line[1] > current[0] * lo + current[1]:
                add(line, node * 2, lo, mid)
            elif line[0] * hi + line[1] > current[0] * hi + current[1]:
                add(line, node * 2 + 1, mid + 1, hi)

        def query(x, node, lo, hi):
            line = tree[node]
            best = line[0] * x + line[1] if line is not None else -10**30
            if lo == hi:
                return best
            mid = (lo + hi) // 2
            if x <= mid:
                return max(best, query(x, node * 2, lo, mid))
            return max(best, query(x, node * 2 + 1, mid + 1, hi))

        add((nums[0], 0), 1, 0, n - 1)
        answer = 0
        for j in range(1, n):
            dp_j = query(j, 1, 0, n - 1)
            if j == n - 1:
                answer = dp_j
            else:
                add((nums[j], dp_j - j * nums[j]), 1, 0, n - 1)

        return answer

