class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        freq = {}
        for value in nums:
            freq[value] = freq.get(value, 0) + 1

        for outlier in sorted(nums, reverse=True):
            remainder = total - outlier
            if remainder % 2 == 0:
                sum_value = remainder // 2
                # The sum element must occupy a different index from the outlier.
                if freq.get(sum_value, 0) - (1 if sum_value == outlier else 0) > 0:
                    return outlier

