class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        lower = 10 ** (len(str(n)) - 1)
        upper = 10 ** len(str(n)) - 1

        is_prime = [True] * (upper + 1)
        is_prime[0] = is_prime[1] = False
        for p in range(2, int(upper ** 0.5) + 1):
            if is_prime[p]:
                for multiple in range(p * p, upper + 1, p):
                    is_prime[multiple] = False

        if is_prime[n] or is_prime[m]:
            return -1

        # The starting value is included in the total transformation cost.
        distances = {n: n}
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != distances[value]:
                continue
            if value == m:
                return cost

            digits = list(map(int, str(value)))
            for i, digit in enumerate(digits):
                for next_digit in (digit - 1, digit + 1):
                    if not 0 <= next_digit <= 9:
                        continue
                    changed = digits.copy()
                    changed[i] = next_digit
                    neighbor = int(''.join(map(str, changed)))
                    if neighbor < lower or is_prime[neighbor]:
                        continue
                    next_cost = cost + neighbor
                    if next_cost < distances.get(neighbor, float('inf')):
                        distances[neighbor] = next_cost
                        heapq.heappush(heap, (next_cost, neighbor))

        return -1

