from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # Z[i] is the LCP of nums and nums[i:]; used for nums1 being
        # a prefix of nums2.
        z = [0] * n
        z[0] = n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        # lcp[j] holds LCP(nums[i:], nums[j:]) for the current i.
        # On moving i backwards, compute each row using the previous row:
        # lcp(i,j) = 1 + lcp(i+1,j+1) when nums[i] == nums[j].
        lcp = [0] * (n + 1)
        answer = 0
        for i in range(n - 2, 0, -1):
            for j in range(i + 1, n):
                lcp[j] = lcp[j + 1] + 1 if nums[i] == nums[j] else 0
                first_is_prefix = (j >= 2 * i and z[i] >= i)
                second_is_prefix = (lcp[j] >= j - i)
                if first_is_prefix or second_is_prefix:
                    answer += 1
        return answer

