class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n, m = len(source), len(pattern)
        target = set(targetIndices)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0
        for i, c in enumerate(source):
            w = int(i in target)
            ndp = [neg] * (m + 1)
            for j in range(m + 1):
                if dp[j] != neg:
                    ndp[j] = dp[j] + w
                    if j < m and c == pattern[j]:
                        if dp[j] > ndp[j + 1]:
                            ndp[j + 1] = dp[j]
            dp = ndp
        return dp[m]

