class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        ones = s.count('1')
        t = '1' + s + '1'
        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        best_gain = 0
        for k in range(1, len(runs) - 1):
            if runs[k][0] == '1':
                # This 1-run is removed and joins the two adjacent zero-runs;
                # converting that merged run gains precisely their total length.
                best_gain = max(best_gain, runs[k - 1][1] + runs[k + 1][1])
        return ones + best_gain

