  vs=set('aeiou'); ans=0
  for i in range(len(word)):
   seen=set(); c=0
   for j in range(i,len(word)):
    if word[j] in vs: seen.add(word[j])
    else: c+=1
    if c>k: break
    ans += c==k and len(seen)==5
  return ans

